"use client";

import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface NewPackageModalProps {
  onClose: () => void;
  onSubmit: (packageData: any) => void;
}

export function NewPackageModal({ onClose, onSubmit }: NewPackageModalProps) {
  const [formData, setFormData] = useState({
    trackingNumber: "",
    description: "",
    sender: "",
    expectedDate: "",
    estimatedTime: "",
    deliveryInstructions: "",
    status: "Pending",
    location: "Warehouse",
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit(formData);
  };

  const handleInputChange = (field: string, value: string) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  return (
    <Dialog open={true} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>Register New Package</DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="trackingNumber">Resident Name</Label>
              <Input
                id="trackingNumber"
                placeholder="Enter Resident Name"
                value={formData.trackingNumber}
                onChange={(e) =>
                  handleInputChange("trackingNumber", e.target.value)
                }
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="trackingNumber">Flat Number</Label>
              <Input
                id="trackingNumber"
                placeholder="Enter Flat Number"
                value={formData.trackingNumber}
                onChange={(e) =>
                  handleInputChange("trackingNumber", e.target.value)
                }
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="trackingNumber">Tracking Number </Label>
              <Input
                id="trackingNumber"
                placeholder="Enter tracking number"
                value={formData.trackingNumber}
                onChange={(e) =>
                  handleInputChange("trackingNumber", e.target.value)
                }
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="sender">Sender </Label>
              <Input
                id="sender"
                placeholder="e.g., Amazon, Flipkart"
                value={formData.sender}
                onChange={(e) => handleInputChange("sender", e.target.value)}
                required
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Package Description </Label>
            <Input
              id="description"
              placeholder="Brief description of the package"
              value={formData.description}
              onChange={(e) => handleInputChange("description", e.target.value)}
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="expectedDate">Expected Date </Label>
              <Input
                id="expectedDate"
                type="date"
                value={formData.expectedDate}
                onChange={(e) =>
                  handleInputChange("expectedDate", e.target.value)
                }
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="estimatedTime">Estimated Time</Label>
              <Select
                value={formData.estimatedTime}
                onValueChange={(value) =>
                  handleInputChange("estimatedTime", value)
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select time slot" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="9:00 AM - 11:00 AM">
                    9:00 AM - 11:00 AM
                  </SelectItem>
                  <SelectItem value="11:00 AM - 1:00 PM">
                    11:00 AM - 1:00 PM
                  </SelectItem>
                  <SelectItem value="1:00 PM - 3:00 PM">
                    1:00 PM - 3:00 PM
                  </SelectItem>
                  <SelectItem value="3:00 PM - 5:00 PM">
                    3:00 PM - 5:00 PM
                  </SelectItem>
                  <SelectItem value="5:00 PM - 7:00 PM">
                    5:00 PM - 7:00 PM
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="deliveryInstructions">Delivery OTP</Label>
            <Input
              id="deliveryInstructions"
              placeholder="Enter OTP for delivery..."
              value={formData.deliveryInstructions}
              onChange={(e) =>
                handleInputChange("deliveryInstructions", e.target.value)
              }
            />
          </div>

          <div className="flex gap-3 pt-4">
            <Button type="submit" className="flex-1">
              Register Package
            </Button>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}
