"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Plus, Package, Truck, CheckCircle, Clock, MapPin } from "lucide-react";
import { PackageModal } from "@/components/package-modal";
import { NewPackageModal } from "@/components/new-package-modal";

const packages = [
  {
    id: "PKG002",
    trackingNumber: "TN987654321",
    description: "Flipkart Package - Books",
    sender: "Flipkart",
    expectedDate: "2024-08-07",
    status: "Delivered",
    location: "Reception Desk",
    recipient: "John Doe",
    flatNumber: "204",
    deliveryInstructions: "Hand to resident only",
    estimatedTime: "10:00 AM - 12:00 PM",
  },
  {
    id: "PKG003",
    trackingNumber: "TN456789123",
    description: "Medical Supplies",
    sender: "PharmEasy",
    expectedDate: "2024-08-09",
    status: "Pending",
    location: "Warehouse",
    recipient: "John Doe",
    flatNumber: "204",
    deliveryInstructions: "Urgent delivery required",
    estimatedTime: "9:00 AM - 11:00 AM",
  },
];

const getStatusColor = (status: string) => {
  switch (status) {
    case "Pending":
      return "bg-yellow-100 text-yellow-800";
    case "In Transit":
      return "bg-blue-100 text-blue-800";
    case "Out for Delivery":
      return "bg-purple-100 text-purple-800";
    case "Delivered":
      return "bg-green-100 text-green-800";
    case "Failed":
      return "bg-red-100 text-red-800";
    default:
      return "bg-gray-100 text-gray-800";
  }
};

const getStatusIcon = (status: string) => {
  switch (status) {
    case "Pending":
      return <Clock className="w-4 h-4" />;
    case "In Transit":
      return <Truck className="w-4 h-4" />;
    case "Out for Delivery":
      return <MapPin className="w-4 h-4" />;
    case "Delivered":
      return <CheckCircle className="w-4 h-4" />;
    default:
      return <Package className="w-4 h-4" />;
  }
};

export default function PackagesPage() {
  const [selectedTab, setSelectedTab] = useState("all");
  const [selectedPackage, setSelectedPackage] = useState(null);
  const [showNewPackageModal, setShowNewPackageModal] = useState(false);
  const [packageList, setPackageList] = useState(packages);

  const filteredPackages = packageList.filter((pkg) => {
    if (selectedTab === "all") return true;
    return pkg.status.toLowerCase().replace(" ", "-") === selectedTab;
  });

  const handleAddPackage = (newPackage: any) => {
    const packageWithId = {
      ...newPackage,
      id: `PKG${String(packageList.length + 1).padStart(3, "0")}`,
      flatNumber: "204",
      recipient: "John Doe",
    };
    setPackageList([...packageList, packageWithId]);
    setShowNewPackageModal(false);
  };

  return (
    <div className="p-6">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Package Tracking</h1>
          <p className="text-gray-600">
            Track and manage your package deliveries
          </p>
        </div>
        <Button onClick={() => setShowNewPackageModal(true)}>
          <Plus className="w-4 h-4 mr-2" />
          Register Package
        </Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">Total</p>
                <p className="text-2xl font-bold">{packageList.length}</p>
              </div>
              <div className="w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center">
                <Package className="w-4 h-4 text-blue-600" />
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">Delivered</p>
                <p className="text-2xl font-bold">
                  {packageList.filter((p) => p.status === "Delivered").length}
                </p>
              </div>
              <div className="w-8 h-8 bg-green-100 rounded-full flex items-center justify-center">
                <CheckCircle className="w-4 h-4 text-green-600" />
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">Pending</p>
                <p className="text-2xl font-bold">
                  {packageList.filter((p) => p.status === "Pending").length}
                </p>
              </div>
              <div className="w-8 h-8 bg-yellow-100 rounded-full flex items-center justify-center">
                <Clock className="w-4 h-4 text-yellow-600" />
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      <Tabs
        value={selectedTab}
        onValueChange={setSelectedTab}
        className="space-y-4"
      >
        <TabsList>
          <TabsTrigger value="all">All</TabsTrigger>
          <TabsTrigger value="pending">Pending</TabsTrigger>
          <TabsTrigger value="delivered">Delivered</TabsTrigger>
        </TabsList>

        <TabsContent value={selectedTab} className="space-y-4">
          {filteredPackages.map((pkg) => (
            <Card
              key={pkg.id}
              className="cursor-pointer hover:shadow-md transition-shadow"
            >
              <CardHeader>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <CardTitle className="text-lg">{pkg.description}</CardTitle>
                    <Badge
                      variant="outline"
                      className={getStatusColor(pkg.status)}
                    >
                      <div className="flex items-center gap-1">
                        {getStatusIcon(pkg.status)}
                        {pkg.status}
                      </div>
                    </Badge>
                  </div>
                  <div className="text-sm text-gray-500">
                    {pkg.trackingNumber}
                  </div>
                </div>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  <div className="grid grid-cols-2 gap-4 text-sm text-gray-600">
                    <span>Sender: {pkg.sender}</span>
                    <span>Expected: {pkg.expectedDate}</span>
                    <span>Location: {pkg.location}</span>
                    <span>Time: {pkg.estimatedTime}</span>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </TabsContent>
      </Tabs>

      {selectedPackage && (
        <PackageModal
          package={selectedPackage}
          onClose={() => setSelectedPackage(null)}
        />
      )}

      {showNewPackageModal && (
        <NewPackageModal
          onClose={() => setShowNewPackageModal(false)}
          onSubmit={handleAddPackage}
        />
      )}
    </div>
  );
}
